SELECT p.first_name, p.country_code, p.player_id FROM players p JOIN matches m ON p.player_id = m.loser_id JOIN rankings r ON m.match_num = r.ranking_date GROUP BY p.player_id ORDER BY p.rankings.ranking_points DESC LIMIT 1;
SELECT year, COUNT(*) AS num_matches FROM matches GROUP BY year ORDER BY num_matches DESC LIMIT 1;
SELECT year, COUNT(*) AS count FROM matches GROUP BY year ORDER BY count DESC LIMIT 1
SELECT p.first_name, p.rankings.ranking_points AS rank_points FROM players p JOIN rankings r ON p.player_id = r.player_id WHERE r.rankings_points = (SELECT MAX(rankings.ranking_points) FROM rankings r2 WHERE r2.player_id = p.player_id)
SELECT p.first_name, p.last_name, r.ranking_points FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.ranking_points DESC LIMIT 1;
SELECT p.first_name, p.last_name, p.country_code, m.best_of, m.draw_size, m.loser_age, m.loser_entry, m.loser_hand, m.loser_name, m.loser_rank, m.loser_rank_points, m.loser_seed, m.match_num, m.minutes, m.round, m.score, m.surface, m.tourney_date, m.tourney_id, m.tourney_level, m.tourney_name, p.winner_age, p.winner_entry, p.winner_hand, p.winner_ht, p.winner_id, p.winner_ioc, p.winner_name, p.winner_rank, p.winner_rank_points, p.winner_seed, m.year FROM players p JOIN matches m ON p.player_id = m.winner_id;
SELECT p.first_name, p.last_name, m.winner_name, m.loser_name, m.winner_rank_points, m.loser_rank_points FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.tourney_name = 'Australian Open' AND m.winner_rank_points > m.loser_rank_points ORDER BY m.winner_rank_points DESC;
SELECT p.first_name, p.last_name, p.hand, p.birth_date, p.country_code, m.minutes, m.round, m.match_num FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.round = (SELECT MAX(round) FROM matches) ORDER BY m.minutes DESC;
SELECT p.first_name, p.last_name, m.loser_name, m.best_of FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.best_of = (SELECT MAX(best_of) FROM matches) ORDER BY p.first_name, p.last_name;
SELECT players.first_name, AVG(matches.loser_rank) AS average_ranking FROM players JOIN matches ON matches.loser_id = players.player_id;
SELECT p.first_name, AVG(r.ranking_points) AS average_rankings FROM players p INNER JOIN rankings r ON p.player_id = r.player_id;
SELECT players.first_name, players.last_name, SUM(ranking_points) AS total_ranking_points FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.player_id
SELECT players.first_name, players.last_name, rankings.ranking_points FROM players JOIN rankings ON players.player_id = rankings.player_id;
SELECT country_code, COUNT(player_id) AS num_players FROM players GROUP BY country_code
SELECT country_code, COUNT(player_id) AS count FROM players GROUP BY country_code
SELECT country_code FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY country_code ORDER BY ranking_points DESC LIMIT 1
SELECT country_code FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY country_code ORDER BY ranking_points DESC LIMIT 1
SELECT player_id, country_code FROM players JOIN matches ON matches.winner_id = players.player_id WHERE matches.round = 2 AND matches.minutes > 50000
SELECT country_code FROM players JOIN matches ON players.player_id = matches.loser_id WHERE matches.round IS NOT NULL AND matches.minutes > 50000
SELECT COUNT(DISTINCT rankings.ranking) AS total_tours FROM rankings JOIN players ON rankings.player_id = players.player_id;
SELECT DISTINCT players.player_id, rankings.ranking, rankings.ranking_points, rankings.tours FROM players INNER JOIN rankings ON rankings.player_id = players.player_id GROUP BY players.player_id
SELECT year, COUNT(*) AS num_matches FROM matches GROUP BY year
SELECT players.year, COUNT(matches.year) AS total_matches_per_year FROM players JOIN matches ON matches.loser_id = players.player_id GROUP BY players.year
SELECT p.first_name, p.rankings.ranking FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.rankings.ranking, p.rankings.ranking_points, p.rankings.ranking_date LIMIT 3;
SELECT players.first_name, players.last_name, matches.loser_rank FROM players JOIN matches ON players.player_id = matches.loser_id WHERE matches.round = 'youngest' ORDER BY players.first_name, players.last_name LIMIT 3;
SELECT COUNT(DISTINCT players.player_id) FROM players INNER JOIN matches ON players.player_id = matches.winner_id INNER JOIN rankings ON players.player_id = rankings.player_id WHERE rankings.rank = 1 AND players.hand = 'L'
SELECT COUNT(*) FROM players INNER JOIN matches ON players.player_id = matches.winner_id;
SELECT players.first_name, players.last_name, matches.winner_rank_points FROM players JOIN matches ON players.player_id = matches.winner_id WHERE matches.loser_rank_points IS NULL ORDER BY matches.winner_rank_points DESC LIMIT 1;
SELECT p.first_name, p.last_name, r.ranking_points AS winner_rank_points FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.ranking_points DESC LIMIT 1;
SELECT COUNT(*) AS total_players, hand_type FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY hand_type
SELECT DISTINCT hand, COUNT(*) AS count FROM players JOIN matches ON players.player_id = matches.loser_id GROUP BY hand;
SELECT Addresses.line_1, Addresses.line_2, Addresses.line_3, Addresses.city, Addresses.zip_postcode, Addresses.state_province_county, Addresses.country, Addresses.other_address_details FROM Addresses WHERE Addresses.address_id IS NOT NULL;
SELECT DISTINCT Addresses.line_1, Addresses.line_2, Addresses.line_3, Addresses.city, Addresses.zip_postcode FROM Addresses WHERE Addresses.address_id IN (SELECT Addresses.address_id FROM Addresses) ORDER BY Addresses.city ASC
SELECT COUNT(*) FROM performance p JOIN show s ON p.Performance_ID = s.Performance_ID WHERE s.If_first_show = '1'
SELECT COUNT(*) FROM conductor
SELECT Name, Year_of_Work FROM conductor ORDER BY Name ASC;
SELECT Name, Year_of_Work FROM conductor ORDER BY birthday;
SELECT Name FROM conductor;
SELECT Name FROM conductor WHERE Nationality = 'American'
SELECT orchestra.Record_Company FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID ORDER BY orchestra.Year_of_Founded ASC;
SELECT orchestra.Orchestra, conductor.Name, conductor.Nationality, orchestra.Year_of_Founded, orchestra.Record_Company FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID ORDER BY orchestra.Year_of_Founded ASC;
SELECT AVG(Attendance) FROM show WHERE If_first_show = 'No' GROUP BY Show_ID
SELECT AVG(show.Attendance) AS average_attendance FROM show INNER JOIN performance ON show.Performance_ID = performance.Performance_ID INNER JOIN orchestra ON performance.Orchestra_ID = orchestra.Orchestra_ID;
SELECT MAX(Weekly_rank), MIN(Share) FROM performance WHERE Type != 'Live final'
SELECT MAX(Share), MIN(Share) FROM performance INNER JOIN show ON performance.Performance_ID = show.Performance_ID WHERE show.Type != 'Live final'
SELECT DISTINCT Nationality FROM conductor;
SELECT DISTINCT Nationality FROM conductor;
SELECT Name, Year_of_Work FROM conductor ORDER BY Year_of_Work ASC;
SELECT Name, Age FROM conductor ORDER BY Age ASC;
SELECT conductor.Name, conductor.Year_of_Work FROM conductor JOIN performance ON conductor.Conductor_ID = performance.Orchestra_ID JOIN orchestra ON orchestra.Orchestra_ID = performance.Orchestra_ID GROUP BY conductor.Name ORDER BY conductor.Year_of_Work DESC LIMIT 1;
SELECT conductor.Name, conductor.Year_of_Work FROM conductor JOIN performance ON conductor.Conductor_ID = performance.Conductor_ID JOIN orchestra ON performance.Orchestra_ID = orchestra.Orchestra_ID GROUP BY conductor.Conductor_ID ORDER BY conductor.Year_of_Work DESC;
SELECT conductor.Name, orchestra.Orchestra FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;
SELECT conductor.Name, orchestra.Orchestra FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;
SELECT Name FROM conductor WHERE Conductor_ID IN (SELECT Conductor_ID FROM orchestra JOIN performance ON orchestra.Conductor_ID = performance.Orchestra_ID AND performance.Type = 'Orchestra' AND orchestra.Record_Company IS NULL GROUP BY Conductor_ID HAVING COUNT(*) > 1)
SELECT Name FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID WHERE orchestra.Orchestra_ID IN (SELECT Orchestra_ID FROM performance JOIN show ON performance.Performance_ID = show.Performance_ID GROUP BY Orchestra_ID HAVING COUNT(Orchestra_ID) > 1)
SELECT conductor.Name AS conductor_name, COUNT(orchestra.Orchestra) AS total_orchestras FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID GROUP BY conductor.Conductor_ID ORDER BY COUNT(orchestra.Orchestra) DESC;
SELECT conductor.Name, orchestra.Orchestra, conductor.Conductor_ID, conductor.Year_of_Work FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID ORDER BY conductor.Year_of_Work DESC;
SELECT conductor.Name, orchestra.Orchestra FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID WHERE orchestra.Year_of_Founded = (SELECT MIN(Year_of_Founded) FROM orchestra) GROUP BY conductor.Conductor_ID, conductor.Name
SELECT Name FROM conductor WHERE Year_of_Work = (SELECT Year_of_Founded FROM orchestra ORDER BY Year_of_Founded DESC LIMIT 1)
SELECT DISTINCT conductor.Name, orchestra.Record_Company, orchestra.Orchestra_ID FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;
SELECT COUNT(DISTINCT orchestra.Orchestra) AS orchestras_per_record_company FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID
SELECT orchestra.Major_Record_Format FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID ORDER BY orchestra.Year_of_Founded ASC;
SELECT orchestra.Major_Record_Format, orchestra.Year_of_Founded FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID ORDER BY orchestra.Year_of_Founded ASC;
SELECT orchestra.Orchestra, conductor.Name, conductor.birthday, conductor.Nationality, conductor.Year_of_Work, orchestra.Record_Company, orchestra.Year_of_Founded, performance.Share FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID ORDER BY conductor.birthday ASC LIMIT 1;
SELECT orchestra.Record_Company FROM orchestra JOIN performance ON orchestra.Orchestra = performance.Orchestra_ID JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE performance.Weekly_rank IS NULL ORDER BY orchestra.Orchestra_ID DESC;
SELECT orchestra.Orchestra FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE conductor.Nationality IS NULL;
SELECT orchestra.Orchestra FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE conductor.Nationality IS NULL;
SELECT orchestra.Record_Company FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE orchestra.Year_of_Founded < 2003
SELECT DISTINCT orchestra.Record_Company FROM orchestra INNER JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE orchestra.Year_of_Founded > 2003 AND conductor.Nationality IS NULL;
