SELECT Owners.owner_id, Owners.first_name, Owners.last_name, Owners.street, Owners.city, Owners.state, Owners.zip_code, Owners.email_address, Owners.home_phone, Owners.cell_number, Owners.owner_id, Owners.name FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id WHERE Dogs.dogs_count > 0 GROUP BY Owners.owner_id ORDER BY Owners.owner_id DESC;
SELECT Professionals.professional_id, Owners.street, Owners.cell_number, Professionals.email_address, Professionals.home_phone, Professionals.cell_number FROM Professionals JOIN Owners ON Professionals.owner_id = Owners.owner_id WHERE Professionals.role_code = 'Professional' AND Professionals.email_address IS NOT NULL AND Professionals.home_phone IS NOT NULL AND Professionals.cell_number IS NOT NULL GROUP BY Professionals.professional_id
SELECT p.professional_id, p.first_name, p.last_name, t.treatment_type_code, t.date_of_treatment, t.cost_of_treatment FROM Professionals p JOIN Treatments t ON p.professional_id = t.professional_id WHERE t.treatment_type_code IN (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_code = '2') AND t.treatment_type_code IN (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_code = '3') AND p.professional_id IN (SELECT professional_id FROM Treatments WHERE treatment_type_code IN (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_code = '2') AND treatment_type_code IN (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_code = '3'))
SELECT breed_name FROM Breeds WHERE breed_code IN (SELECT Dogs.breed_code FROM Dogs JOIN Treatments ON Dogs.breed_code = Treatments.treatment_type_code JOIN Professionals ON Treatments.professional_id = Professionals.professional_id JOIN Owners ON Dogs.owner_id = Owners.owner_id GROUP BY breed_code ORDER BY COUNT(Dogs.dog_id) DESC LIMIT 1)
SELECT breed_name FROM Breeds WHERE breed_code IN (SELECT breed_code FROM Dogs WHERE abandoned_yn = '1') GROUP BY breed_code ORDER BY breed_name DESC;
SELECT Owners.owner_id, Owners.last_name, Charges.charge_amount, Treatments.cost_of_treatment FROM Owners INNER JOIN Charges ON Owners.owner_id = Charges.charge_id INNER JOIN Treatments ON Treatments.treatment_type_code = Treatments.treatment_type_code WHERE Treatments.treatment_type_code = Treatments.treatment_type_code;
SELECT Dogs.owner_id, Dogs.last_name, Owners.owner_id, Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Dogs.date_of_treatment DESC LIMIT 1;
SELECT treatment_type_description, cost_of_treatment FROM Treatments INNER JOIN Charges ON Treatments.treatment_type_code = Charges.charge_type JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code ORDER BY cost_of_treatment ASC LIMIT 1;
SELECT treatment_type_description FROM Treatment_Types WHERE cost_of_treatment < (SELECT MIN(cost_of_treatment) FROM Charges)
SELECT o.owner_id, o.zip_code, o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Sizes s ON d.size_code = s.size_code JOIN Breeds b ON d.breed_code = b.breed_code WHERE d.abandoned_yn = 'N' AND t.cost_of_treatment = (SELECT MAX(cost_of_treatment) FROM Treatments t WHERE t.dog_id = d.dog_id) ORDER BY o.zip_code DESC;
SELECT Owners.owner_id, Owners.zip_code FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id INNER JOIN Charges ON Dogs.dog_id = Charges.charge_id INNER JOIN Sizes ON Dogs.size_code = Sizes.size_code INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code GROUP BY Owners.owner_id ORDER BY Charges.charge_amount DESC LIMIT 1;
SELECT Professionals.professional_id, Professionals.first_name, Professionals.last_name FROM Professionals JOIN Dogs ON Dogs.owner_id = Professionals.owner_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Charges ON Charges.charge_id = Treatments.dog_id JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code JOIN Owners ON Owners.owner_id = Professionals.owner_id WHERE Professionals.role_code = 'Professional' AND Treatments.treatment_type_code IN ('Type1', 'Type2')
SELECT o.owner_id, o.first_name, o.last_name, t.home_phone, t.cell_number, p.professional_id FROM Owners o JOIN Professionals p ON o.owner_id = p.owner_id JOIN Dogs d ON d.owner_id = o.owner_id JOIN Treatment_Types t ON d.dog_id = t.dog_id JOIN Treatments t ON d.dog_id = t.dog_id WHERE p.role_code = 'Professional' AND t.treatment_type_code IN ('Treatments', 'Services')
SELECT DISTINCT p.first_name, p.last_name FROM Professionals p JOIN Treatments t ON t.professional_id = p.professional_id JOIN Dogs d ON t.dog_id = d.dog_id WHERE t.cost_of_treatment < (SELECT MIN(cost_of_treatment) FROM Charges c)
SELECT o.first_name, o.last_name, d.name, t.cost_of_treatment FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id WHERE t.cost_of_treatment < (SELECT AVG(t.cost_of_treatment) FROM Treatments t) GROUP BY o.first_name, o.last_name, d.name, t.cost_of_treatment
SELECT Dogs.date_of_birth, Professionals.first_name, Professionals.last_name FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id;
SELECT Dogs.name, Professionals.first_name, Professionals.last_name FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.dog_id IN (SELECT Dogs.dog_id FROM Treatments) LIMIT 10;
SELECT Dogs.name, Treatment_Types.treatment_type_description, Charges.charge_amount FROM Dogs INNER JOIN Charges ON Dogs.dog_id = Charges.charge_id INNER JOIN Treatment_Types ON Charges.charge_type = Treatment_Types.treatment_type_code;
SELECT Dogs.name, Treatment_Types.treatment_type_description, Charges.charge_amount FROM Dogs INNER JOIN Charges ON Dogs.owner_id = Charges.charge_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code;
SELECT o.first_name, o.last_name, d.size_code, d.size_description FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Sizes s ON d.size_code = s.size_code;
SELECT Dogs.name, Dogs.size_code FROM Dogs JOIN Sizes ON Dogs.size_code = Sizes.size_code;
SELECT Dogs.name, Owners.first_name, Owners.last_name, Dogs.owner_id, Dogs.breed_code, Dogs.size_code, Dogs.name FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Dogs.name;
SELECT Dogs.name, Owners.first_name, Owners.last_name FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Treatments.date_of_treatment FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE Treatments.cost_of_treatment IS NULL AND Treatments.date_of_treatment IS NOT NULL;
SELECT Dogs.name, Treatment_Types.treatment_type_description, Treatments.date_of_treatment FROM Dogs JOIN Treatment_Types ON Dogs.breed_code = Treatment_Types.treatment_type_code JOIN Treatments ON Treatments.dog_id = Dogs.dog_id;
SELECT o.first_name, d.name FROM Owners o INNER JOIN Dogs d ON o.owner_id = d.owner_id;
SELECT Dogs.name, Owners.first_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'VA' AND Dogs.abandoned_yn = 'N' AND Dogs.owner_id = Owners.owner_id;
SELECT d.date_departed, t.date_of_treatment FROM Dogs d JOIN Treatments t ON d.dog_id = t.dog_id JOIN Treatment_Types t1 ON t.treatment_type_code = t1.treatment_type_code WHERE d.date_of_birth <= t.date_of_treatment AND d.date_of_birth >= t.date_of_treatment;
SELECT t.date_of_treatment AS treatment_period FROM Treatments t JOIN Dogs d ON t.dog_id = d.dog_id;
SELECT Dogs.owner_id, Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.age = (SELECT MIN(age) FROM Dogs)
SELECT Owners.last_name, Dogs.age FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id WHERE Dogs.age = (SELECT MIN(age) FROM Dogs)
SELECT Owners.email_address FROM Owners JOIN Dogs ON Dogs.owner_id = Owners.owner_id JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code JOIN Professionals ON Professionals.owner_id = Owners.owner_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE Owners.state = 'HI' OR Owners.state = 'WI' AND Professionals.state = 'HI' OR Professionals.state = 'WI';
SELECT email_address FROM Owners JOIN Professionals ON Owners.owner_id = Professionals.owner_id WHERE Professionals.state IN ('HI', 'WI')
SELECT Dogs.date_arrived, Dogs.date_departed FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id;
SELECT Dogs.date_departed, Dogs.date_arrived FROM Dogs WHERE Dogs.abandoned_yn = 'A';
SELECT COUNT(*) FROM Dogs;
SELECT COUNT(DISTINCT Dogs.dog_id) FROM Dogs;
SELECT COUNT(DISTINCT Professionals.professional_id) FROM Professionals INNER JOIN Treatments ON Treatments.professional_id = Professionals.professional_id;
SELECT COUNT(*) FROM Professionals INNER JOIN Dogs ON Professionals.owner_id = Dogs.owner_id;
