SELECT COUNT(DISTINCT Dogs.dog_id) FROM Dogs WHERE Dogs.abandoned_yn = 'Y' AND Dogs.age < (SELECT AVG(Dogs.age) FROM Dogs)
SELECT COUNT(DISTINCT Dogs.age) FROM Dogs WHERE Dogs.abandoned_yn = 'Y' AND Dogs.age < (SELECT AVG(Dogs.age) FROM Dogs)
SELECT cost_of_treatment FROM Treatments WHERE date_of_treatment = (SELECT MAX(date_of_treatment) FROM Treatments)
SELECT MAX(cost_of_treatment) FROM Treatments;
SELECT COUNT(DISTINCT Dogs.dog_id) FROM Dogs WHERE Dogs.abandoned_yn = 'A' AND Dogs.date_departed IS NULL;
SELECT COUNT(DISTINCT Dogs.dog_id) FROM Dogs;
SELECT COUNT(DISTINCT Dogs.owner_id) FROM Dogs WHERE Dogs.abandoned_yn = 'N' AND Dogs.date_departed IS NULL;
SELECT COUNT(DISTINCT Owners.owner_id) FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id WHERE Dogs.abandoned_yn = 'N' AND Dogs.breed_code IS NOT NULL;
SELECT COUNT(DISTINCT Professionals.professional_id) FROM Professionals INNER JOIN Dogs ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.abandoned_yn = 'N' AND Dogs.breed_code IS NULL;
SELECT COUNT(DISTINCT Professionals.professional_id) FROM Professionals INNER JOIN Treatments ON Treatments.professional_id = Professionals.professional_id WHERE Treatments.treatment_type_code = 'none' AND Treatments.dog_id IS NULL;
SELECT Dogs.name, Dogs.age, Dogs.weight, Dogs.abandoned_yn FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Dogs.age, Dogs.weight, Dogs.abandoned_yn FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.abandoned_yn = '1' AND Dogs.abandoned_yn IS NOT NULL;
SELECT AVG(Dogs.age) FROM Dogs;
SELECT AVG(Dogs.age) FROM Dogs;
SELECT Dogs.age, Treatments.cost_of_treatment FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id WHERE Treatments.cost_of_treatment IS NULL;
SELECT Dogs.age AS age, Dogs.date_of_birth AS date_of_birth, Dogs.date_departed AS date_departed FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Dogs.age DESC LIMIT 1;
SELECT charge_type, charge_amount FROM Charges;
SELECT Charges.charge_type, Charges.charge_amount FROM Charges;
SELECT MAX(charge_amount) AS max_cost FROM Charges;
SELECT MAX(charge_amount) FROM Charges;
SELECT Dogs.name, Professionals.first_name, Professionals.last_name, Professionals.email_address, Professionals.home_phone, Professionals.cell_number FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id;
SELECT Professionals.first_name, Professionals.last_name, Professionals.email_address, Professionals.home_phone, Professionals.cell_number FROM Professionals JOIN Dogs ON Professionals.professional_id = Dogs.owner_id JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.breed_code, Dogs.size_code, Treatments.treatment_type_code, Treatments.cost_of_treatment FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code JOIN Sizes ON Dogs.size_code = Sizes.size_code;
SELECT DISTINCT breed_name, size_description FROM Dogs JOIN Sizes ON Dogs.size_code = Sizes.size_code;
SELECT Professionals.first_name, Professionals.last_name, Treatment_Types.treatment_type_description AS treatment_type_description FROM Professionals JOIN Treatment_Types ON Professionals.professional_id = Treatments.professional_id JOIN Dogs ON Dogs.dog_id = Treatments.dog_id JOIN Owners ON Dogs.owner_id = Owners.owner_id JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code;
SELECT Professionals.first_name, Professionals.last_name, Treatments.cost_of_treatment FROM Professionals INNER JOIN Treatments ON Professionals.professional_id = Treatments.professional_id;
