SELECT COUNT(*) AS count_of_singers FROM singer;
SELECT Name FROM singer ORDER BY Birth_Year ASC
SELECT Name FROM singer ORDER BY Birth_Year ASC
SELECT Singer_ID, Birth_Year, Citizenship FROM singer;
SELECT Singer_ID, Citizenship FROM singer ORDER BY Birth_Year;
SELECT Name FROM singer WHERE Citizenship != 'French' AND Name IS NOT NULL
SELECT Name FROM singer WHERE Citizenship != 'French' AND Name IS NOT NULL
SELECT Name FROM singer WHERE Birth_Year < 1948
SELECT Name FROM singer WHERE Birth_Year <= 1948
SELECT Name FROM singer WHERE Birth_Year = (SELECT MIN(Birth_Year) FROM singer)
SELECT Name FROM singer WHERE Birth_Year = (SELECT MIN(Birth_Year) FROM singer)
SELECT DISTINCT Citizenship, COUNT(*) AS Number_of_Singers FROM singer GROUP BY Citizenship;
SELECT Citizenship, COUNT(Singer_ID) AS Total_Singers FROM singer GROUP BY Citizenship
SELECT Citizenship, COUNT(*) AS Most_Common_Citizenship FROM singer GROUP BY Citizenship ORDER BY COUNT(*) DESC;
SELECT DISTINCT Citizenship FROM singer;
SELECT Citizenship, MAX(Song.Highest_Position) AS Highest_Net_Worth FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID GROUP BY Citizenship;
SELECT Citizenship, MAX(Net_Worth_Millions) AS Highest_Net_Worth FROM singer GROUP BY Citizenship
SELECT song.Title, singer.Name AS singer_name FROM song INNER JOIN singer ON song.Singer_ID = singer.Singer_ID ORDER BY song.Highest_Position DESC;
SELECT DISTINCT singer.Name, song.Highest_Position FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID ORDER BY singer.Name DESC;
SELECT DISTINCT singer.Name FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID WHERE song.Sales > 3000000;
SELECT DISTINCT Name FROM singer WHERE Net_Worth_Millions > 300000;
SELECT Name FROM singer WHERE Singer_ID IN (SELECT Singer_ID FROM song WHERE Sales > 0 AND Song_ID IN (SELECT Song_ID FROM song WHERE Sales > 0 AND Highest_Position = 1))
SELECT Name FROM singer WHERE Birth_Year IS NOT NULL AND Net_Worth_Millions IS NOT NULL AND Singer_ID IN (SELECT Singer_ID FROM song WHERE Sales IS NOT NULL)
SELECT s.Name, s.Sales, s.Highest_Position FROM singer s JOIN song s ON s.Singer_ID = song.Singer_ID;
SELECT DISTINCT singer.Name, MAX(song.Highest_Position) AS Max_Highest_Position FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID GROUP BY singer.Name;
SELECT Name FROM singer WHERE Singer_ID NOT IN (SELECT Singer_ID FROM song WHERE Sales IS NULL)
SELECT s.Name AS sname FROM singer s JOIN song s ON s.Singer_ID = song.Singer_ID WHERE s.Sales IS NULL
